var n=`0613-rechta`;var i=`world-0613`;var s=`DZ`;var a=`northern-africa`;var o=4;var r=91;var h={en:`Rechta`,ua:`Решта`};var g={en:`Rechta is a Algeria classic prepared with all-purpose flour, chicken egg, chicken thigh, yellow onion. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Решта, страва кухні країни Алжир зі складниками: пшеничне борошно універсальне, куряче яйце, куряче стегно, жовта цибуля. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 25 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 25 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:25,i:[[`all-purpose-flour`,390,`g`],[`water`,150,`ml`],[`chicken-egg`,2,`pcs`],[`table-salt`,5,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:10,i:[]},{en:`Steam the cut fresh noodle strips in batches until tender, keeping them loose rather than packed together.`,ua:`Пропарте нарізані смужки свіжої локшини порціями до м’якості, щоб вони не злипалися.`,t:[`steaming`],m:14,i:[]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`chicken-thigh`,650,`g`],[`yellow-onion`,210,`g`],[`unsalted-butter`,55,`g`],[`ground-cinnamon`,3,`g`]]},{en:`Spread steamed noodles on a platter, top with chicken and ladle over its chickpea broth.`,ua:`Розкладіть пропарену локшину на тарелі, додайте курку й полийте нутовою підливою.`,t:[`stewing`],m:28,i:[[`canned-chickpeas`,240,`g`],[`chicken-stock`,650,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,25,`g`]]}];var l={slug:n,id:i,country:`DZ`,region:a,servings:4,minutes:91,title:h,text:g,steps:d};export{s as country,l as default,i as id,r as minutes,a as region,o as servings,n as slug,d as steps,g as text,h as title};